(* [comment removed for export] *)
Definition AT (t : Z) (R1 : bvmap 5 word) (RC : list Z) (Dc : list (list Z)) (M1 : mem) (model1 : Model) (LK1 : list fframe) (Aw1 : list (Z * Z))
           (s1 : PQMA.mpst) (sm1 : PM.strm) (e1 : bool) (cr1 : credit) : Prop :=
  MM RC Dc M1 model1 LK1 Aw1 s1 sa sm1 e1 cr1 eb /\ REGS R1
  /\ getr R1 (reg 10) = Z_to_bv 64 1 /\ getr R1 (reg 23) = Z_to_bv 64 (F + 96) /\ getr R1 (reg 24) = Z_to_bv 64 (fb + 592 + 24)
  /\ L5.u8_at RSEGS M1 (F + 96) t /\ 0 <= t < 256
  /\ PQMA.cpl s1 (NEMA.ae_a sa) /\ PQRA.minv_d 0 s1 /\ PQMA.p_stk s1 = PQMA.p_stk s /\ PQMA.p_bb s1 = PQMA.p_bb s
  /\ PQMA.pot_mparser (PMSPA.HV L ar) s1 = PQMA.pot_mparser (PMSPA.HV L ar) s
  /\ PM.unread (PQMA.p_src s1) sm1 + 1 <= PM.unread (PQMA.p_src s) sm /\ 0 <= PM.unread (PQMA.p_src s1) sm1
  /\ RIC cr1 (pot_runA s1 sa) (tsp Dc RC0).


