Lemma TAILZ (c v : Z) (fx2 fx5 : FPState) R2 R5 RC Dc M3 model3 LK3 Aw3 s1 sa1 sm1 cr3 (ra : Z) (M5v : mem) :
  MM RC Dc M3 model3 LK3 Aw3 s1 sa1 sm1 true cr3 true -> REGS R2 -> 1 <= v <= 64 ->
  PQMA.cpl s1 (NEMA.ae_a sa1) -> PQMA.acct n s1 (NEMA.ae_a sa1) sm1 ->
  RIC cr3 (pot_runA s1 sa1) (tsp Dc RC0) ->
