Lemma TAILV2 (g1 g2 c dk dphi : Z) (ts : Prop) (fx2 fx5 : FPState) R2 R5 RC Dc M3 model3 LK3 Aw3 s1 sa3 sm1 e1 cr1 cr3 (b1 b3 : bool) (ra : Z) (M5v : mem) :
  MM RC Dc M3 model3 LK3 Aw3 s1 sa3 sm1 e1 cr3 b3 -> REGS R2 ->
  PQMA.cpl s1 (NEMA.ae_a sa) -> PQRA.minv_d 0 s1 -> PQMA.p_stk s1 = PQMA.p_stk s -> PQRA.room_keep s s1 sm sm1 ->
  PM.unread (PQMA.p_src s1) sm1 + c <= PM.unread (PQMA.p_src s) sm -> 1 <= c ->
  NEMA.ae_ok sa3 -> PNVA.step_val dk dphi ts sa sa3 b1 b3 -> dk <= 7 * c -> dphi <= 8 * c ->
  RIC cr1 (pot_runA s1 sa) (tsp Dc RC0) ->
  PMSP.credit_keep cr1 cr3 (NEMA.pot_aeA L ar sa) (NEMA.pot_aeA L ar sa3) ->
  msteps RSEGS (st fx2 R2 ra (mrestrict (ahid Aw3 model3) M3)) (st fx5 R5 0xd09ac M5v) ->
  mem_grows (mrestrict (ahid Aw3 model3) M3) M5v ->
  0 <= g1 < 128 -> 0 <= g2 < 128 ->
  (forall i, 0 <= i < 2 ^ 64 -> ~ (fb + 592 + 8 <= i < fb + 592 + 8 + 1) -> ~ (F / 8 + 2147450880 + g1 <= i < F / 8 + 2147450880 + g1 + 1) ->
     ~ (F / 8 + 2147450880 + g2 <= i < F / 8 + 2147450880 + g2 + 1) -> ~ (F / 8 + 2147450880 + 12 <= i < F / 8 + 2147450880 + 12 + 1) ->
     M5v (Z_to_bv 64 i) = mrestrict (ahid Aw3 model3) M3 (Z_to_bv 64 i)) ->
  (forall x, In x RL -> getr R5 (reg x) = getr R2 (reg x)) ->
  L5.u8_at RSEGS M5v (fb + 592 + 8) 1 ->
  srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx2 R2 ra M3 model3) K.
