(* [comment removed for export] *)
Lemma GSZ (t ra : Z) (fx1 fx2 : FPState) R1 R2 RC Dc M1 model1 LK1 Aw1 s1 sm1 e1 cr1 (M2v : mem) :
  PNRNA.get_size_spec RSEGS AD AQ AAD AE L ar (HIk Dc) ->
  AT t R1 RC Dc M1 model1 LK1 Aw1 s1 sm1 e1 cr1 -> PQRA.gs_type t ->
  msteps RSEGS (st fx1 R1 0xd081c (mrestrict (ahid Aw1 model1) M1)) (st fx2 R2 0xd3904 M2v) ->
  mem_grows (mrestrict (ahid Aw1 model1) M1) M2v ->
  (forall i, 0 <= i < 2 ^ 64 -> M2v (Z_to_bv 64 i) = mrestrict (ahid Aw1 model1) M1 (Z_to_bv 64 i)) ->
  (forall x, In x RL -> getr R2 (reg x) = getr R1 (reg x)) ->
  getr R2 (reg 1) = Z_to_bv 64 ra -> L5.ra_ok ra -> getr R2 (reg 10) = Z_to_bv 64 (fb + 592) -> getr R2 (reg 11) = Z_to_bv 64 t -> getr R2 (reg 12) = Z_to_bv 64 (fb + 1232) ->
  getr R2 (reg 23) = Z_to_bv 64 (F + 96) -> getr R2 (reg 24) = Z_to_bv 64 (fb + 592 + 24) ->
  (forall (fx3 : FPState) R3 (M3 : mem) model3 LK3 Aw3 s3 sa3 sm3 e3 cr3 b3,
      REGS R3 -> getr R3 (reg 23) = Z_to_bv 64 (F + 96) -> getr R3 (reg 24) = Z_to_bv 64 (fb + 592 + 24) ->
      MM RC Dc M3 model3 LK3 Aw3 s3 sa3 sm3 e3 cr3 b3 ->
      RIC cr3 (pot_runA s3 sa3) (tsp Dc RC0) ->
      (forall a, spc <= a < 2 ^ 47 -> M3 (Z_to_bv 64 a) = M1 (Z_to_bv 64 a)) ->
      ((b3 = true /\ PQMA.p_more s3 = 0)
       \/ (b3 = eb /\ PQMA.cpl s3 (NEMA.ae_a sa3) /\ PQMA.acct n s3 (NEMA.ae_a sa3) sm3 /\ NEMA.oacct n s3 sa3 sm3
           /\ sa3 = sa /\ PQRA.minv_d 0 s3 /\ PQMA.p_stk s3 = PQMA.p_stk s /\ PQRA.room_keep s s3 sm sm3
           /\ PM.unread (PQMA.p_src s3) sm3 + 1 <= PM.unread (PQMA.p_src s) sm /\ exists len, 0 <= len < 2 ^ 64 /\ getr R3 (reg 10) = Z_to_bv 64 len)) ->
      srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx3 R3 ra M3 model3) K) ->
