(* [comment removed for export] *)
Definition ts_entry (L : asan_layout) (ar : asan_run) (HIk : list (list Z) -> asan_iface) (tsp : list (list Z) -> list Z -> credit)
    (K : TSet) (R : bvmap 5 word) (M : mem) (model : Model) (LBX : list (Z * Z)) (FF LK : list fframe) (Aw : list (Z * Z)) (cr : credit)
    (V2 cls fb cat : Z) (D0 : list (list Z)) (s : PQMA.mpst) (sa : NEMA.aest) (str : PM.vstr) (sm : PM.strm) (e eb : bool) (RC0 : list Z) (F : Z)
    (c len dat gsh : Z)
    (R3 : bvmap 5 word) (RC : list Z) (Dc : list (list Z)) (M3 : mem) (model3 : Model) (LK3 : list fframe) (Aw3 : list (Z * Z))
    (s3 : PQMA.mpst) (sm3 : PM.strm) (e3 : bool) (cr3 : credit) : Prop :=
  PQARIK.ri_mem L ar HIk D0 M model LBX FF LK Aw (V2 + cls) fb cat s str sm e eb (V2 - 160) (PQARI1.own (V2 + cls) R) F RC Dc M3 model3 LK3 Aw3 s3 sa sm3 e3 cr3 eb
  /\ PQARI1.REGS R V2 cls fb F R3
  /\ getr R3 (reg 10) = Z_to_bv 64 8 /\ getr R3 (reg 23) = Z_to_bv 64 8 /\ getr R3 (reg 24) = Z_to_bv 64 (fb + 592 + 24) /\ getr R3 (reg 25) = Z_to_bv 64 (F + dat)
  /\ PQMA.cpl s3 (NEMA.ae_a sa) /\ PQRA.minv_d 0 s3 /\ PQMA.p_stk s3 = PQMA.p_stk s /\ PQRA.room_keep s s3 sm sm3
  /\ PM.unread (PQMA.p_src s3) sm3 + c <= PM.unread (PQMA.p_src s) sm /\ 0 <= PM.unread (PQMA.p_src s3) sm3
  /\ PQARIK.ric L cr (PNRNA.pot_runA L ar s sa) (tsp D0 RC0) cr3 (PNRNA.pot_runA L ar s3 sa) (tsp Dc RC0)
  /\ L5.u64_at RSEGS M3 (V2 - 152) len /\ L5.u64_at RSEGS M3 (V2 - 144) ((fb + 592 + 8) / 8 + 2147450880) /\ L5.u64_at RSEGS M3 (V2 - 136) (fb + 592 + 8)
  /\ L5.u8_at RSEGS M3 (F + 384) 255 /\ L5.u8_at RSEGS M3 (F / 8 + 2147450928) 1
  /\ L5.defined M3 (F + dat) 8 /\ L5.u8_at RSEGS M3 (F / 8 + gsh) 0.

(* [comment removed for export] *)
Definition in_ctx (L : asan_layout) (ar : asan_run) (C : asan_statics_cells) (IL : icpt_layout) (LR : HAR.layoutR) (HIk : list (list Z) -> asan_iface)
    (tsp : list (list Z) -> list Z -> credit) (TSRESA : credit)
    (T : forall (K : TSet) (R : bvmap 5 word) (M : mem) (model : Model) (LBX : list (Z * Z)) (FF LK : list fframe) (Aw : list (Z * Z)) (cr : credit)
                 (V2 cls r fb cat n : Z) (D0 : list (list Z)) (s : PQMA.mpst) (sa : NEMA.aest) (str : PM.vstr) (sm : PM.strm) (e eb : bool) (RC0 : list Z)
                 (F fl : Z) (LK2 : list fframe) (M2 : mem) (model2 : Model), Prop) : Prop :=
  PMA.layout L C -> HAR.asan_famR_ok L ar C SCFG LR HIk -> (forall D, aicpt_ok L ar IL SCFG (HIk D)) -> as0_icpt_layout IL ->
  (forall D RC, PMSP.credit_le PMSP.cr0 (tsp D RC) /\ PMSP.credit_le (tsp D RC) TSRESA) ->
  forall (K : TSet) (R : bvmap 5 word) (M : mem) (model : Model) (LBX : list (Z * Z)) (FF LK : list fframe) (Aw : list (Z * Z)) (cr : credit)
         (V2 cls r fb cat n : Z) (D0 : list (list Z)) (s : PQMA.mpst) (sa : NEMA.aest) (str : PM.vstr) (sm : PM.strm) (e eb : bool) (RC0 : list Z),
  cls = 0 \/ cls = 16 -> V2 mod 32 = 0 ->
  ri_inv (HIk D0) (mown s sa ++ LBX) FF LK cr Aw M (vml_of model) -> L5CA.amodel_ok Aw model -> K [] ->
  PMSPA.entryA AD L ar R M (V2 + cls) r 10 -> PGSA.ffroomB PQRA.FCM 10 FF LK -> PMSPA.ffrsA FF (V2 + cls) -> PQRA.frame_okM FF fb ->
  getr R (reg 10) = Z_to_bv 64 (fb + 592) -> getr R (reg 11) = Z_to_bv 64 (fb + 992) -> getr R (reg 12) = Z_to_bv 64 (fb + 1232) ->
  PNRNA.mrun_pre RSEGS AD AQ AAD AE L ar M fb s sa str sm e eb cat n -> incl (PM.vs_own str) LBX ->
  HAR.rchain L ar M (V2 + cls) (bv_unsigned (getr R (reg 8))) RC0 -> PQRA.bb_room s sm -> PQRA.minv_d 0 s ->
  PMSP.credit_le (PM.credit_add (PM.credit_add (PNRNA.pot_runA L ar s sa) (PMSPA.scA L PNRNA.TSRES_ME)) (tsp D0 RC0)) cr ->
  (forall (fx' : FPState) (R' : bvmap 5 word) (M' : mem) (model' : Model) (LK' : list fframe) (Aw' : list (Z * Z))
          (s' : PQMA.mpst) (st' : NEMA.aest) (sm' : PM.strm) (e' b' : bool) (cr' : credit) (D' : list (list Z)),
      regs_preserved R R' ->
      PNRNA.mrun_post_d RSEGS AD AQ AAD AE L ar 0 PNRNA.mprog_item R' M' fb s s' sa st' str sm sm' e e' eb b' cat n ->
      L5CA.ahpres L ar LBX FF (V2 + cls) (PMSPA.pm_scr 10) (PNRNA.W_mrun AD AQ AE fb) M M' ->
      PMSP.credit_keep cr cr' (PM.credit_add (PNRNA.pot_runA L ar s sa) (tsp D0 RC0)) (PM.credit_add (PNRNA.pot_runA L ar s' st') (tsp D' RC0)) ->
      model_rt model model' -> incl LK' LK -> incl Aw Aw' -> L5CA.amodel_ok Aw' model' -> incl D0 D' ->
      ri_inv (HIk D') (mown s' st' ++ LBX) FF LK' cr' Aw' M' (vml_of model') ->
      srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx' R' r M' model') K) ->
  forall (F fl : Z) (LK2 : list fframe) (M2 : mem) (model2 : Model),
  PQAKUF.gctx L ar HIk D0 LBX FF LK Aw (V2 + cls) (PMSPA.pm_scr 10) (V2 - 160) (V2 - 160) (V2 + cls) (PQARI1.ocell (V2 + cls)) (PQARI1.own (V2 + cls) R) F fl 4 LK2 M2 model2 cr (mown s sa) ->
  (forall a n0 sp0 scr0, (forall i, 0 <= i < n0 -> aclient L ar (mown s sa ++ LBX) FF sp0 scr0 (a + i)) -> 0 < n0 ->
         (a + n0 <= F \/ F + ff_bytes 4 <= a) /\ (a + n0 <= F / 8 + SB \/ F / 8 + SB + ff_bytes 4 / 8 <= a) /\ (a + n0 <= fl \/ fl + 1 <= a)) ->
  T K R M model LBX FF LK Aw cr V2 cls r fb cat n D0 s sa str sm e eb RC0 F fl LK2 M2 model2.

(* [comment removed for export] *)
Definition TS8A (L : asan_layout) (ar : asan_run) (C : asan_statics_cells) (IL : icpt_layout) (LR : HAR.layoutR) (HIk : list (list Z) -> asan_iface)
    (tsp : list (list Z) -> list Z -> credit) (TSRESA : credit) : Prop :=
  in_ctx L ar C IL LR HIk tsp TSRESA (fun K R M model LBX FF LK Aw cr V2 cls r fb cat n D0 s sa str sm e eb RC0 F fl LK2 M2 model2 =>
    forall (fx3 : FPState) (R3 : bvmap 5 word) (RC : list Z) (Dc : list (list Z)) (M3 : mem) (model3 : Model) (LK3 : list fframe) (Aw3 : list (Z * Z))
           (s3 : PQMA.mpst) (sm3 : PM.strm) (e3 : bool) (cr3 : credit),
      ts_entry L ar HIk tsp K R M model LBX FF LK Aw cr V2 cls fb cat D0 s sa str sm e eb RC0 F 10 8 416 2147450932 R3 RC Dc M3 model3 LK3 Aw3 s3 sm3 e3 cr3 ->
      srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx3 R3 0xd11a8 M3 model3) K).

(* [comment removed for export] *)
Definition TS12A (L : asan_layout) (ar : asan_run) (C : asan_statics_cells) (IL : icpt_layout) (LR : HAR.layoutR) (HIk : list (list Z) -> asan_iface)
    (tsp : list (list Z) -> list Z -> credit) (TSRESA : credit) : Prop :=
  in_ctx L ar C IL LR HIk tsp TSRESA (fun K R M model LBX FF LK Aw cr V2 cls r fb cat n D0 s sa str sm e eb RC0 F fl LK2 M2 model2 =>
    forall (fx3 : FPState) (R3 : bvmap 5 word) (RC : list Z) (Dc : list (list Z)) (M3 : mem) (model3 : Model) (LK3 : list fframe) (Aw3 : list (Z * Z))
           (s3 : PQMA.mpst) (sm3 : PM.strm) (e3 : bool) (cr3 : credit) (nsr : Z),
      ts_entry L ar HIk tsp K R M model LBX FF LK Aw cr V2 cls fb cat D0 s sa str sm e eb RC0 F 14 12 560 2147450950 R3 RC Dc M3 model3 LK3 Aw3 s3 sm3 e3 cr3 ->
      L5.defined M3 (F + 544) 4 -> L5.u8_at RSEGS M3 (F / 8 + 2147450948) 4 -> L5.defined M3 (V2 - 160) 8 ->
      In r PQRAR.RS_A -> bv_unsigned (getr R (reg 8)) <> V2 + cls + 8 -> L5.u64_at RSEGS M3 (V2 - 160) nsr -> 0 <= nsr < 2 ^ 32 ->
      srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx3 R3 0xd1a04 M3 model3) K).
End Defs.
