Module PQARIKX.
Import L5A L5SAR.
Ltac inl := apply L5K.In_of_mem; vm_compute; reflexivity.
Abbreviation reg i := (Z_to_bv 5 (Z.of_nat i)).
Abbreviation RSEGS := Asan.M.loaded_segments.
Abbreviation mem := (word -> option byte).
Abbreviation AD := PMA.AD.
Abbreviation AAD := PMA.AAD.
Abbreviation AQ := PnLayoutQA.QADDR_A.
Abbreviation accA := PMSPA.accA.
Abbreviation annA := PMSPA.annA.
Abbreviation mparser_at := (PQMA.mparser_at RSEGS AD accA PMSPA.annA (pa_vp_parser AD)).
Abbreviation adaptor_at := (PQMA.adaptor_at RSEGS AD accA PMSPA.annA (qa_vp_adaptor AQ)).
Abbreviation AE := NemLayoutA.NEADDR_A.
Abbreviation W_mrun := (PNRNA.W_mrun AD AQ AE).
Abbreviation mown := PNRNA.mown.
Abbreviation ec_stateA := (NEMA.ec_stateA RSEGS AD).
