Section WithHeap.
Context {SCFG_P : ScfgP}.
Variables (L : asan_layout) (ar : asan_run) (C : asan_statics_cells) (IL : icpt_layout) (LR : HAR.layoutR) (HIk : list (list Z) -> asan_iface) (D0 : list (list Z))
          (tsp : list (list Z) -> list Z -> credit) (TSRESA : credit).
Hypothesis LY : PMA.layout L C.
Hypothesis FAMok : HAR.asan_famR_ok L ar C SCFG LR HIk.
Hypothesis ICokF : forall D, aicpt_ok L ar IL SCFG (HIk D).
Hypothesis ILY : as0_icpt_layout IL.
Hypothesis TSPB : forall D RC, PMSP.credit_le PMSP.cr0 (tsp D RC) /\ PMSP.credit_le (tsp D RC) TSRESA.
Let LYa := PMA.ly_as0 L C LY.
Let HIokF (D : list (list Z)) := HAR.fr_base L ar C SCFG LR HIk FAMok D.
Local Notation mrun_pre := (PNRNA.mrun_pre RSEGS AD AQ AAD AE L ar).
Local Notation mrun_fin := (PNRNA.mrun_fin RSEGS AD AQ AAD AE L ar).
Local Notation pot_runA := (PNRNA.pot_runA L ar).
Local Notation ae_atA := (NEMA.ae_atA RSEGS AD AE L ar (qa_vp_adaptor AQ)).

(* [comment removed for export] *)
Lemma fin_after LB1 FFx spx scr Wc (M1 M4 : mem) fb0 s1 s4 st str0 sm1 sm4 e1 e4 b1 cat0 :
  (forall f, In f FFx -> 0 <= ff_addr f /\ ff_addr f + ff_bytes (ff_class f) <= 2 ^ 47) -> (forall b, In b LB1 -> 0 <= fst b /\ fst b + snd b <= 2 ^ 47) ->
  ek L ar LB1 FFx spx scr Wc M1 M4 -> PMKA.wapp Wc -> PQRA.frame_okM FFx fb0 -> incl (NEMA.aeown st) LB1 ->
  (forall i, (fb0 + 432 <= i < fb0 + 456 \/ fb0 + 496 <= i < fb0 + 552 \/ fb0 + 992 <= i < fb0 + 1096 \/ fb0 + 1232 <= i < fb0 + 1248) -> L5.outside Wc i) ->
  (forall B0 m, In (B0, m) (NEMA.aeown st) -> forall i, B0 <= i < B0 + m -> L5.outside Wc i) ->
  mrun_fin M1 fb0 s1 st str0 sm1 e1 b1 cat0 ->
  mparser_at M4 (fb0 + 592) (fb0 + 96) s4 -> PM.iss_at RSEGS AD accA M4 (fb0 + 96) str0 sm4 -> PQMA.mgrow_ok s4 ->
  PMSTA.base_okA RSEGS AD M4 -> PQSTA.err_okA RSEGS AD AAD AQ M4 e4 ->
  mrun_fin M4 fb0 s4 st str0 sm4 e4 b1 cat0.
