(* [comment removed for export] *)
Section Fn.
Variables (K : TSet) (R : bvmap 5 word) (M : mem) (model : Model) (LBX : list (Z * Z)) (FF LK : list fframe) (Aw : list (Z * Z)) (cr : credit)
          (sp r fb cat n : Z) (s : PQMA.mpst) (sa : NEMA.aest) (str : PM.vstr) (sm : PM.strm) (e eb : bool).
Hypothesis HH : ri_inv (HIk D0) (mown s sa ++ LBX) FF LK cr Aw M (vml_of model).
Hypothesis AM : L5CA.amodel_ok Aw model.
Hypothesis K0 : K [].
Hypothesis ENT : PMSPA.entryA AD L ar R M sp r 10.
Hypothesis FRM : PGSA.ffroomB PQRA.FCM 10 FF LK.
Hypothesis FRS : PMSPA.ffrsA FF sp.
Hypothesis FOK : PQRA.frame_okM FF fb.
Hypothesis RPRE : mrun_pre M fb s sa str sm e eb cat n.
Hypothesis INCS : incl (PM.vs_own str) LBX.
(* [comment removed for export] *)
Variable RC0 : list Z.
Hypothesis RCH0 : HAR.rchain L ar M sp (bv_unsigned (getr R (reg 8))) RC0.
Hypothesis ROOM0 : PQRA.bb_room s sm.
Hypothesis INV0 : PQRA.minv_d 0 s.
Hypothesis CRED0 : PMSP.credit_le (PM.credit_add (PM.credit_add (pot_runA s sa) (PMSPA.scA L PNRNA.TSRES_ME)) (tsp D0 RC0)) cr.
Hypothesis KONT : forall (fx' : FPState) (R' : bvmap 5 word) (M' : mem) (model' : Model) (LK' : list fframe) (Aw' : list (Z * Z))
            (s' : PQMA.mpst) (st' : NEMA.aest) (sm' : PM.strm) (e' b' : bool) (cr' : credit) (D' : list (list Z)),
    regs_preserved R R' ->
    PNRNA.mrun_post_d RSEGS AD AQ AAD AE L ar 0 PNRNA.mprog_item R' M' fb s s' sa st' str sm sm' e e' eb b' cat n ->
    L5CA.ahpres L ar LBX FF sp (PMSPA.pm_scr 10) (W_mrun fb) M M' ->
    PMSP.credit_keep cr cr' (PM.credit_add (pot_runA s sa) (tsp D0 RC0)) (PM.credit_add (pot_runA s' st') (tsp D' RC0)) ->
    model_rt model model' -> incl LK' LK -> incl Aw Aw' -> L5CA.amodel_ok Aw' model' -> incl D0 D' ->
    ri_inv (HIk D') (mown s' st' ++ LBX) FF LK' cr' Aw' M' (vml_of model') ->
    srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx' R' r M' model') K.
(* [comment removed for export] *)
Variables (spc : Z) (ocell : Z -> Prop) (own : mem -> Prop) (F fl : Z) (LK2 : list fframe) (M2 : mem) (model2 : Model).
Hypothesis G : PQAKUF.gctx L ar HIk D0 LBX FF LK Aw sp (PMSPA.pm_scr 10) spc spc sp ocell own F fl 4 LK2 M2 model2 cr (mown s sa).
Hypothesis APART : forall a n0 sp0 scr0, (forall i, 0 <= i < n0 -> aclient L ar (mown s sa ++ LBX) FF sp0 scr0 (a + i)) -> 0 < n0 ->
         (a + n0 <= F \/ F + ff_bytes 4 <= a) /\ (a + n0 <= F / 8 + SB \/ F / 8 + SB + ff_bytes 4 / 8 <= a) /\ (a + n0 <= fl \/ fl + 1 <= a).
Hypothesis HSPC : sp - 176 <= spc /\ spc + 160 <= sp /\ spc mod 32 = 0.
Hypothesis HOC16 : forall a, sp - 16 <= a < sp -> ocell a.
Local Notation B := (ff_bytes 4).
Local Notation FF' := ((F, 4, spc + 32) :: FF).
Local Notation SCR := (PMSPA.pm_scr 10).
Local Notation WR := (W_mrun fb).

(* [comment removed for export] *)
(* [comment removed for export] *)
Ltac inb H := clear - H; rewrite ?in_app_iff in H; rewrite ?in_app_iff; tauto.

Definition ri_memX (XB : list (Z * Z)) (RC : list Z) (Dc : list (list Z)) (M1 : mem) (model1 : Model) (LK1 : list fframe) (Aw1 : list (Z * Z)) (s1 : PQMA.mpst) (sa1 : NEMA.aest) (sm1 : PM.strm) (e1 : bool)
           (cr1 : credit) (b1 : bool) : Prop :=
  incl D0 Dc
  /\ PQAKUF.binv L ar HIk Dc M model LBX FF LK Aw sp SCR spc own F 4 WR ((XB ++ mown s1 sa1)) M1 model1 LK1 cr1 Aw1
  /\ mrun_fin M1 fb s1 sa1 str sm1 e1 b1 cat
  /\ (eb = true -> b1 = true)
  /\ PMSP.src_step (PQMA.p_src s) (PQMA.p_src s1) sm sm1 /\ (e = true -> e1 = true)
  /\ HAR.rchain L ar M1 spc sp RC.

(* [comment removed for export] *)
Lemma ctx_facts :
  (7036928 <= fb /\ fb + 2048 <= ahl_ceil ar /\ fb mod 2048 = 0 /\ (2147446784 + 17592186048512 <= fb \/ fb + 2048 <= 2147446784))
  /\ (ahl_ceil ar + 4096 + SCR <= sp /\ sp <= ar_sptop ar /\ 140735340871680 <= ar_sptop ar <= 2 ^ 47 /\ sp mod 16 = 0)
  /\ (exists rs, In (fb, 5, rs) FF)
