(* [comment removed for export] *)
Lemma binv_pieceS Dc BX Mc modelc LKc crc Ac M1 model1 (Wp : Z -> Prop) :
  incl D0 Dc ->
  PQAKUF.binv L ar HIk Dc M model LBX FF LK Aw sp SCR spc own F 4 WR BX Mc modelc LKc crc Ac ->
  ri_inv (HIk Dc) (BX ++ LBX) FF' LKc crc Ac M1 (vml_of model1) -> L5CA.amodel_ok Ac model1 -> model_rt modelc model1 -> mem_grows Mc M1 ->
  (forall a, 0 <= a < 2 ^ 64 -> ~ Wp a -> M1 (Z_to_bv 64 a) = Mc (Z_to_bv 64 a)) ->
  (forall a, Wp a -> ~ ocell a /\ ((sp - SCR <= a < sp) \/ ~ L5.outside WR a \/ (exists q m, In (q, m) BX /\ q <= a < q + m)
                                  \/ (F <= a < F + B \/ F / 8 + SB <= a < F / 8 + SB + B / 8))) ->
  PQAKUF.binv L ar HIk Dc M model LBX FF LK Aw sp SCR spc own F 4 WR BX M1 model1 LKc crc Ac.
Proof using All.
