Definition Wobj (s1 : PQMA.mpst) (a : Z) : Prop :=
  (sp - SCR <= a < sp) \/ (fb + 600 <= a < fb + 608) \/ (fb + 920 <= a < fb + 992) \/ (exists q m, In (q, m) (PQMA.mparser_own s1) /\ q <= a < q + m)
  \/ ((F <= a < F + B - 8 /\ ~ (F + 24 <= a < F + 32)) \/ (F / 8 + SB <= a < F / 8 + SB + B / 8)).
