(* [comment removed for export] *)
Lemma ri_piece_tb XB RC Dc M1 model1 LK1 Aw1 s1 sa1 sm1 e1 cr1 b1 (fx1 fx2 : FPState) R1 R2 (pc1 pc2 : Z) (M2v : mem) (W : Z -> Prop) (x0 : PM.vstr) :
  ri_memX XB RC Dc M1 model1 LK1 Aw1 s1 sa1 sm1 e1 cr1 b1 ->
  msteps RSEGS (st fx1 R1 pc1 (mrestrict (ahid Aw1 model1) M1)) (st fx2 R2 pc2 M2v) ->
  mem_grows (mrestrict (ahid Aw1 model1) M1) M2v ->
  (forall a, 0 <= a < 2 ^ 64 -> ~ W a -> M2v (Z_to_bv 64 a) = mrestrict (ahid Aw1 model1) M1 (Z_to_bv 64 a)) ->
  (forall a, W a -> ~ ocell a /\ ((sp - SCR <= a < sp) \/ (fb + 920 <= a < fb + 944) \/ (exists q m, In (q, m) (PM.vs_own (PQMA.p_tb s1)) /\ q <= a < q + m))) ->
  PM.vs_own x0 = PM.vs_own (PQMA.p_tb s1) -> PQMA.tb_okM x0 ->
  (forall (M3 : mem), mem_grows M1 M3 -> (forall a, 0 <= a < 2 ^ 64 -> ~ W a -> M3 (Z_to_bv 64 a) = M1 (Z_to_bv 64 a)) ->
      mrestrict (ahid Aw1 model1) M3 = M2v -> avis (ahid Aw1 model1) (fb + 920) 24 -> PMFA.agsh M1 M3 (fb + 592) PQMA.PSIZE ->
      (forall q m, In (q, m) (PM.vs_own (PQMA.p_tb s1)) -> PMFA.agsh M1 M3 q m /\ avis (ahid Aw1 model1) q m /\ 0 <= q /\ q + m <= 2 ^ 47) ->
      PM.vstr_at RSEGS accA M1 (fb + 920) (PQMA.p_tb s1) -> PM.vstr_at RSEGS accA M3 (fb + 920) x0) ->
  (forall (M3 : mem) model3,
      ri_memX XB RC Dc M3 model3 LK1 Aw1 (PQAKWT.with_tb s1 x0) sa1 sm1 e1 cr1 b1 ->
      ahid Aw1 model3 = ahid Aw1 model1 -> mrestrict (ahid Aw1 model1) M3 = M2v ->
      (forall a, 0 <= a < 2 ^ 64 -> ~ W a -> M3 (Z_to_bv 64 a) = M1 (Z_to_bv 64 a)) -> mem_grows M1 M3 ->
      srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx2 R2 pc2 M3 model3) K) ->
  srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx1 R1 pc1 M1 model1) K.
